PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "accounts" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL DEFAULT 'google', "provider_account_id" TEXT NULL, "display_name" TEXT NULL, "email" TEXT NULL, "tenant_id" TEXT NULL, "account_avatar_url" TEXT NULL, "provider_metadata_json" TEXT NULL, "auth_state" TEXT NOT NULL DEFAULT 'signed_out', "calendars_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("calendars_enabled" IN (0, 1)), "tasks_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("tasks_enabled" IN (0, 1)), "granted_scopes" TEXT NOT NULL DEFAULT '', "created_at_utc" TEXT NOT NULL, "updated_at_utc" TEXT NOT NULL, "last_successful_sync_at_utc" TEXT NULL, "last_full_sync_at_utc" TEXT NULL, PRIMARY KEY ("id"));
