CREATE TABLE IF NOT EXISTS "task_lists" ("account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "id" TEXT NOT NULL, "kind" TEXT NULL, "etag" TEXT NULL, "title" TEXT NOT NULL, "updated_utc" TEXT NULL, "self_link" TEXT NULL, "raw_json" TEXT NOT NULL, "provider_list_kind" TEXT NULL, "is_owner" INTEGER NULL CHECK ("is_owner" IN (0, 1)), "is_shared" INTEGER NULL CHECK ("is_shared" IN (0, 1)), "delta_link" TEXT NULL, "provider_metadata_json" TEXT NULL, "server_missing" INTEGER NOT NULL DEFAULT 0 CHECK ("server_missing" IN (0, 1)), "local_dirty" INTEGER NOT NULL DEFAULT 0 CHECK ("local_dirty" IN (0, 1)), "pending_delete" INTEGER NOT NULL DEFAULT 0 CHECK ("pending_delete" IN (0, 1)), "last_synced_at_utc" TEXT NULL, "created_local_at_utc" TEXT NOT NULL, "updated_local_at_utc" TEXT NOT NULL, PRIMARY KEY ("account_id", "id"));
