CREATE TABLE IF NOT EXISTS "pending_ops" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "provider" TEXT NULL, "entity_type" TEXT NOT NULL, "operation" TEXT NOT NULL, "operation_type" TEXT NULL, "task_list_id" TEXT NULL, "task_id" TEXT NULL, "calendar_source_id" TEXT NULL, "provider_calendar_id" TEXT NULL, "event_id" TEXT NULL, "local_temp_id" TEXT NULL, "depends_on_op_id" TEXT NULL, "request_json" TEXT NOT NULL, "baseline_updated_utc" TEXT NULL, "baseline_raw_json" TEXT NULL, "attempt_count" INTEGER NOT NULL DEFAULT 0, "next_attempt_at_utc" TEXT NULL, "last_error_code" TEXT NULL, "last_error_message" TEXT NULL, "state" TEXT NOT NULL DEFAULT 'pending', "last_error" TEXT NULL, "created_at_utc" TEXT NOT NULL, "updated_at_utc" TEXT NOT NULL, PRIMARY KEY ("id"));
