CREATE TABLE IF NOT EXISTS "sync_runs" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "provider" TEXT NULL, "mode" TEXT NOT NULL, "started_at_utc" TEXT NOT NULL, "finished_at_utc" TEXT NULL, "status" TEXT NOT NULL, "task_lists_seen" INTEGER NOT NULL DEFAULT 0, "tasks_seen" INTEGER NOT NULL DEFAULT 0, "pending_ops_applied" INTEGER NOT NULL DEFAULT 0, "error_code" TEXT NULL, "error_message" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "calendar_sources" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "provider" TEXT NOT NULL, "provider_calendar_id" TEXT NOT NULL, "summary" TEXT NOT NULL, "description" TEXT NULL, "primary_calendar" INTEGER NOT NULL DEFAULT 0 CHECK ("primary_calendar" IN (0, 1)), "selected" INTEGER NOT NULL DEFAULT 1 CHECK ("selected" IN (0, 1)), "hidden" INTEGER NOT NULL DEFAULT 0 CHECK ("hidden" IN (0, 1)), "read_only" INTEGER NOT NULL DEFAULT 0 CHECK ("read_only" IN (0, 1)), "background_color" TEXT NULL, "foreground_color" TEXT NULL, "color_id" TEXT NULL, "time_zone" TEXT NULL, "access_role" TEXT NULL, "is_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("is_deleted" IN (0, 1)), "raw_json" TEXT NULL, "created_at_local" INTEGER NOT NULL, "updated_at_local" INTEGER NOT NULL, PRIMARY KEY ("id"));
