CREATE TABLE IF NOT EXISTS "calendar_events" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "calendar_source_id" TEXT NOT NULL REFERENCES calendar_sources (id) ON DELETE CASCADE, "provider" TEXT NOT NULL, "provider_calendar_id" TEXT NOT NULL, "provider_event_id" TEXT NOT NULL, "provider_recurring_event_id" TEXT NULL, "provider_original_start_key" TEXT NULL, "etag_or_change_key" TEXT NULL, "status" TEXT NULL, "title" TEXT NOT NULL, "description" TEXT NULL, "location" TEXT NULL, "all_day" INTEGER NOT NULL DEFAULT 0 CHECK ("all_day" IN (0, 1)), "start_date" TEXT NULL, "start_date_time" TEXT NULL, "start_time_zone" TEXT NULL, "end_date" TEXT NULL, "end_date_time" TEXT NULL, "end_time_zone" TEXT NULL, "recurrence_json" TEXT NULL, "reminders_json" TEXT NULL, "attendees_json" TEXT NULL, "categories_json" TEXT NULL, "organizer_json" TEXT NULL, "creator_json" TEXT NULL, "color_id" TEXT NULL, "color_hex" TEXT NULL, "visibility" TEXT NULL, "transparency_or_show_as" TEXT NULL, "event_type" TEXT NULL, "web_link" TEXT NULL, "conference_json" TEXT NULL, "attachments_json" TEXT NULL, "is_cancelled" INTEGER NOT NULL DEFAULT 0 CHECK ("is_cancelled" IN (0, 1)), "is_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("is_deleted" IN (0, 1)), "raw_json" TEXT NULL, "created_at_server" TEXT NULL, "updated_at_server" TEXT NULL, "created_at_local" INTEGER NOT NULL, "updated_at_local" INTEGER NOT NULL, "sync_status" TEXT NOT NULL DEFAULT 'synced', "baseline_raw_json" TEXT NULL, PRIMARY KEY ("id"));
