CREATE TABLE IF NOT EXISTS "calendar_event_attendees" ("id" TEXT NOT NULL, "calendar_event_id" TEXT NOT NULL REFERENCES calendar_events (id) ON DELETE CASCADE, "email" TEXT NOT NULL, "display_name" TEXT NULL, "response_status" TEXT NULL, "optional" INTEGER NOT NULL DEFAULT 0 CHECK ("optional" IN (0, 1)), "organizer" INTEGER NOT NULL DEFAULT 0 CHECK ("organizer" IN (0, 1)), "self" INTEGER NOT NULL DEFAULT 0 CHECK ("self" IN (0, 1)), "raw_json" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "calendar_event_reminders" ("id" TEXT NOT NULL, "calendar_event_id" TEXT NOT NULL REFERENCES calendar_events (id) ON DELETE CASCADE, "provider" TEXT NOT NULL, "method" TEXT NULL, "minutes_before" INTEGER NULL, "absolute_time" TEXT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "raw_json" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "calendar_sync_states" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "calendar_source_id" TEXT NULL REFERENCES calendar_sources (id) ON DELETE CASCADE, "provider" TEXT NOT NULL, "sync_kind" TEXT NOT NULL, "range_start" TEXT NULL, "range_end" TEXT NULL, "google_sync_token" TEXT NULL, "microsoft_delta_link" TEXT NULL, "last_full_sync_at" INTEGER NULL, "last_incremental_sync_at" INTEGER NULL, "last_error" TEXT NULL, "raw_state_json" TEXT NULL, PRIMARY KEY ("id"));
