CREATE TABLE IF NOT EXISTS "calendar_colors" ("provider" TEXT NOT NULL, "color_type" TEXT NOT NULL, "color_id" TEXT NOT NULL, "background" TEXT NOT NULL, "foreground" TEXT NULL, "raw_json" TEXT NULL, PRIMARY KEY ("provider", "color_type", "color_id"));
CREATE TABLE IF NOT EXISTS "schedule_item_overrides" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "source_type" TEXT NOT NULL, "source_id" TEXT NOT NULL, "override_json" TEXT NOT NULL, "created_at_local" INTEGER NOT NULL, "updated_at_local" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "notification_schedule" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "source_type" TEXT NOT NULL, "source_id" TEXT NOT NULL, "scheduled_at_utc" INTEGER NOT NULL, "title" TEXT NOT NULL, "body" TEXT NULL, "sent_at_utc" INTEGER NULL, "dismissed_at_utc" INTEGER NULL, "snoozed_until_utc" INTEGER NULL, "created_at_local" INTEGER NOT NULL, "updated_at_local" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_accounts_provider ON accounts(provider);
CREATE UNIQUE INDEX idx_accounts_provider_account ON accounts(provider, provider_account_id) WHERE provider_account_id IS NOT NULL;
CREATE INDEX idx_task_lists_account_title ON task_lists(account_id, title COLLATE NOCASE);
CREATE INDEX idx_task_lists_dirty ON task_lists(account_id, local_dirty, pending_delete);
CREATE INDEX idx_tasks_list_order ON tasks(account_id, task_list_id, parent, position);
CREATE INDEX idx_tasks_status_due ON tasks(account_id, task_list_id, status, due_utc);
CREATE INDEX idx_tasks_dirty ON tasks(account_id, local_dirty, pending_delete, pending_move);
CREATE INDEX idx_tasks_updated ON tasks(account_id, task_list_id, updated_utc);
CREATE UNIQUE INDEX idx_calendar_sources_provider_id ON calendar_sources(account_id, provider, provider_calendar_id);
CREATE INDEX idx_calendar_sources_visible ON calendar_sources(account_id, selected, hidden, is_deleted);
CREATE UNIQUE INDEX idx_calendar_events_provider_id ON calendar_events(account_id, provider, provider_calendar_id, provider_event_id, provider_original_start_key);
CREATE INDEX idx_calendar_events_range ON calendar_events(account_id, calendar_source_id, all_day, start_date, start_date_time, end_date, end_date_time);
CREATE INDEX idx_calendar_events_dirty ON calendar_events(account_id, sync_status, is_deleted);
CREATE UNIQUE INDEX idx_calendar_sync_states_scope ON calendar_sync_states(account_id, provider, sync_kind, calendar_source_id, range_start, range_end);
CREATE INDEX idx_notification_schedule_due ON notification_schedule(scheduled_at_utc, sent_at_utc, dismissed_at_utc, snoozed_until_utc);
PRAGMA user_version=5;
